<script>
function showAlert(txt, time) {
const overlay = document.getElementById('alertO');
const message = document.getElementById('alertM');
message.textContent = txt;
overlay.style.display = 'flex';
if (time > 0) {
	setTimeout(() => {
		overlay.style.display = 'none';
		}, time);
	}
}
function copy() {
const btn = document.getElementById('btn1');
btn.classList.add('an-s');
const cpt = document.getElementById("copyt");
cpt.select();
try {
    const cpy = document.execCommand("copy");
    if (cpy.length<9) throw '异常';
    showAlert(cpt.value, 1000);
  } catch (e) {alert("复制失败，请手动复制");}
setTimeout(() => {
	btn.classList.remove('an-s');
	}, 450);
}
</script>
</body></html>`;

