<js>
let rr = result.match(/novel:\s*({.+})/)[1];
let id = String(chapter.url).match(/\d+(?=$|,)/)[0];

let bin = book.durChapterIndex;
let cin = chapter.index;
let inn = cin - bin;
if (inn==0) {
let rra = result.match(/authorDetails:\s*({.+})/)[1];
//作者信息
let uid = java.getString('$..userId',rra);
let unm = java.getString('$..userName',rra);
let uim = java.getString('$..url',rra);
uim = uim.replace('i.pximg.net','pximg.hakurei.cc');
let ugz = java.getString('$..isFollowed',rra);
//作品信息
let tags = java.getStringList('$..tags[*]',rr);
tags = Array.from(tags).map(x => `＃${x}`).join(' ');
let caption = String(java.getString('$..caption',rr));
caption = caption ? '<p>'+caption.replace(/(?:<br \/>)+/g, '</p><p>')+'</p>' : '';
let cdate = java.getString('$..cdate',rr);
let xh = java.getString('$..rating.like',rr);
let sc = java.getString('$..rating.bookmark',rr);
let gk = java.getString('$..rating.view',rr);
let title = java.getString('$.title',rr);
let sTitle = java.getString('$.seriesTitle',rr);
//放入信息
cache.putMemory('pxcjj',[title,uid,unm,uim,tags,caption,cdate,xh,sc,gk,sTitle,id,ugz]);
cache.put('pxuid',uid);
cache.put('pxid',id);
let Info=source.getLoginInfoMap();

let sid = java.get('sid');
if (sid != '🇨🇳') {
	Info['书名']=String(book.name).replace(/^📘/,'');
	cache.put('pxsid',sid);} else {
	Info['书名']='';
	cache.put('pxsid','');}

Info['章节'] = chapter.title;
Info['作者'] = book.author.replace('\u200b','');
//放入UI界面
source.putLoginInfo(JSON.stringify(Info));
}

let urls = java.getString('$..urls',rr);
let tt = String(java.getString('$.text',rr));
let img1 = tt.match(/\[uploadedimage\:\d+\]/g)||'';
let img2 = tt.match(/\[pixivimage\:[\d\-]+\]/g)||'';
for (x of img1) {
	let id = x.match(/\d+/)[0];
	let url = java.getString('$..'+id+'.urls.original',rr);
	let re = new RegExp('\\[uploadedimage\\:'+id+'\\]');
	tt = tt.replace(re,'<img src="'+gethdi(url)+'"/>');
	}
for (x of img2) {
	let id = x.match(/[\d\-]+/)[0];
	let url = java.getString('$..'+id+'..images.original',rr);
	if (url=='null') url = java.getString('$..'+id+'..images.medium',rr);
	let re = new RegExp('\\[pixivimage\\:'+id+'\\]');
	tt = tt.replace(re,'<img src="'+gethdi(url)+'"/>');
	}
tt.replaceAll('[newpage]','\n—换页符—\n').replace(/\[\[jumpuri\:(.+)\>.+\]\]/,'🖇️$1🖇️')
